import{_ as n,C as i,c as d,o as l,a6 as s,G as r,j as a,a as t}from"./chunks/framework.BY05barL.js";const D=JSON.parse('{"title":"Latencias de lectura: CPU, memoria y discos","description":"","frontmatter":{},"headers":[],"relativePath":"unidad1/latencias-lectura-cpu-memoria-discos.md","filePath":"unidad1/latencias-lectura-cpu-memoria-discos.md"}'),c={name:"unidad1/latencias-lectura-cpu-memoria-discos.md"};function m(u,e,p,g,h,S){const o=i("IoLatencyEmbed");return l(),d("div",null,[e[0]||(e[0]=s('<h1 id="latencias-de-lectura-cpu-memoria-y-discos" tabindex="-1">Latencias de lectura: CPU, memoria y discos <a class="header-anchor" href="#latencias-de-lectura-cpu-memoria-y-discos" aria-label="Permalink to &quot;Latencias de lectura: CPU, memoria y discos&quot;">​</a></h1><p>Cuando un proceso necesita un dato, el costo no es “una lectura”: depende de <strong>dónde</strong> está ese dato. La diferencia entre registros/caché, RAM, SSD, HDD, cinta o almacenamiento por red es de <strong>órdenes de magnitud</strong>.</p><h2 id="ordenes-de-magnitud-referencia" tabindex="-1">Órdenes de magnitud (referencia) <a class="header-anchor" href="#ordenes-de-magnitud-referencia" aria-label="Permalink to &quot;Órdenes de magnitud (referencia)&quot;">​</a></h2><p>Valores típicos de latencia de acceso (aprox.). Sirven para comparar, no como spec de un hardware concreto.</p><table tabindex="0"><thead><tr><th>Nivel</th><th>Latencia típica</th><th>Equivalente @ ~3 GHz</th></tr></thead><tbody><tr><td>Ciclo de CPU / registro</td><td>~0.3 ns</td><td>~1 ciclo</td></tr><tr><td>Caché L1</td><td>~0.5–1 ns</td><td>~2–3 ciclos</td></tr><tr><td>Caché L2 / L3</td><td>~3–20 ns</td><td>~10–60 ciclos</td></tr><tr><td><strong>RAM (memoria principal)</strong></td><td><strong>~100 ns</strong></td><td><strong>~300 ciclos</strong></td></tr><tr><td><strong>SSD NVMe local</strong></td><td><strong>~16–50 μs</strong></td><td><strong>~50k–150k ciclos</strong></td></tr><tr><td>SSD por red (p. ej. EBS)</td><td>~250 μs</td><td>~750k ciclos</td></tr><tr><td><strong>HDD (seek + lectura)</strong></td><td><strong>~1–10 ms</strong></td><td><strong>~3M–30M ciclos</strong></td></tr><tr><td>Cinta (lectura aleatoria)</td><td>~1 s o más</td><td>~3G ciclos</td></tr></tbody></table><blockquote><p>Relacionado: en <a href="/ucasal-ssoo-estudio/unidad1/lenguaje-maquina-microprogramacion-assembler.html#costos-de-operaciones-de-cpu">Lenguaje máquina…</a> el gráfico de costos expresa la misma idea en ciclos de CPU.</p></blockquote><h2 id="ram-vs-ssd-local" tabindex="-1">RAM vs SSD local <a class="header-anchor" href="#ram-vs-ssd-local" aria-label="Permalink to &quot;RAM vs SSD local&quot;">​</a></h2><p>Round-trip CPU → <strong>RAM ≈ 100 ns</strong>. CPU → <strong>SSD NVMe local ≈ 50 μs</strong> (unas <strong>500×</strong> más lento que la RAM). Por eso los sistemas operativos cachean páginas en memoria y evitan ir a disco siempre que pueden.</p>',8)),r(o,{viz:"io-latency-memory-local-ssd",title:"Comparación animada: memoria (100 ns) vs SSD local (50 μs)","min-height":360}),e[1]||(e[1]=a("h2",{id:"ssd-local-vs-almacenamiento-por-red",tabindex:"-1"},[t("SSD local vs almacenamiento por red "),a("a",{class:"header-anchor",href:"#ssd-local-vs-almacenamiento-por-red","aria-label":'Permalink to "SSD local vs almacenamiento por red"'},"​")],-1)),e[2]||(e[2]=a("p",null,[t("Si el disco “está en la red” del datacenter (volúmenes tipo EBS), cada lectura paga un round-trip de red. Típico: "),a("strong",null,"~250 μs"),t(" frente a "),a("strong",null,"~50 μs"),t(" del NVMe local — otro orden de magnitud de latencia por encima del SSD directo.")],-1)),r(o,{viz:"io-latency-local-ssd-network-ssd",title:"SSD local (~50 μs) vs SSD por red (~250 μs)","min-height":360}),e[3]||(e[3]=a("h2",{id:"hdd-vs-ssd",tabindex:"-1"},[t("HDD vs SSD "),a("a",{class:"header-anchor",href:"#hdd-vs-ssd","aria-label":'Permalink to "HDD vs SSD"'},"​")],-1)),e[4]||(e[4]=a("p",null,[t("Un HDD necesita mover el brazo y esperar el plato. Una lectura aleatoria suele estar en "),a("strong",null,"1–3 ms"),t(". Un SSD moderno puede responder en "),a("strong",null,"~16 μs"),t(": cientos de veces más rápido en acceso aleatorio, porque no hay partes mecánicas.")],-1)),r(o,{viz:"io-latency-hdd-ssd",title:"Lectura aleatoria: HDD vs SSD","min-height":320}),e[5]||(e[5]=a("h2",{id:"cinta-vs-hdd",tabindex:"-1"},[t("Cinta vs HDD "),a("a",{class:"header-anchor",href:"#cinta-vs-hdd","aria-label":'Permalink to "Cinta vs HDD"'},"​")],-1)),e[6]||(e[6]=a("p",null,[t("La cinta sigue usándose para archivo masivo (barata, durable), pero una lectura “lejos” del cabezal puede llevar "),a("strong",null,"segundos"),t(". Un HDD, aunque mecánico, está en el orden de "),a("strong",null,"milisegundos"),t(".")],-1)),r(o,{viz:"io-latency-tape-hdd",title:"Lectura aleatoria: cinta (~1 s) vs HDD (~2 ms)","min-height":320}),e[7]||(e[7]=s('<h2 id="que-implica-para-el-so" tabindex="-1">Qué implica para el SO <a class="header-anchor" href="#que-implica-para-el-so" aria-label="Permalink to &quot;Qué implica para el SO&quot;">​</a></h2><ul><li>Un proceso <strong>bloqueado en E/S</strong> puede “desperdiciar” millones o miles de millones de ciclos de CPU potenciales; el planificador aprovecha eso corriendo otros procesos.</li><li>La <strong>jerarquía de memoria</strong> (registros → caché → RAM → disco) existe precisamente por estas diferencias de latencia y costo.</li><li>Accesos <strong>secuenciales</strong> suelen ser mucho mejores que <strong>aleatorios</strong> en cinta y HDD; en SSD el layout y el GC también importan.</li></ul><p>Para ver cómo se mueven cinta, HDD y SSD “por dentro” (y qué abstrae el SO al leer un archivo), ver <a href="/ucasal-ssoo-estudio/unidad1/funciones-so.html#ejemplo-leer-un-archivo">Funciones de un Sistema Operativo</a>.</p><h2 id="ver-mas" tabindex="-1">Ver más <a class="header-anchor" href="#ver-mas" aria-label="Permalink to &quot;Ver más&quot;">​</a></h2><ul><li>Artículo original: <a href="https://planetscale.com/blog/io-devices-and-latency" target="_blank" rel="noreferrer">IO devices and latency — PlanetScale</a>, de Ben Dicken.</li></ul>',5))])}const b=n(c,[["render",m]]);export{D as __pageData,b as default};
